//! TPC-H fixtures for the strict workload suite.
//!
//! The eight standard tables are generated by the repository's native
//! `tpchgen-rs` UDTFs, committed into the harness-owned namespace and
//! warehouse, and proven from LakeSoul metadata and the published Parquet
//! footers before the read-only server starts. The query files and checked-in
//! answers are never consulted here: this module only materializes the exact
//! dataset those answers were produced from.

use std::collections::BTreeSet;
use std::env::VarError;
use std::fs::File;
use std::path::Path;
use std::time::Duration;

use anyhow::{Context, Result, anyhow, bail, ensure};
use datafusion::arrow::datatypes::{DataType, Schema};
use datafusion::prelude::SessionContext;
use lakesoul_datafusion::tpch::register_tpch_udtfs;
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;

use super::{StartupState, bounded};

/// tpchgen-rs revision pinned by `lakesoul-datafusion`; the checked-in answers
/// were generated from the same dbgen-identical dataset.
pub const TPCH_GENERATOR: &str = "tpchgen-rs@46f3dca";
/// Generator partitions per table for the default PR workload.
pub const TPCH_GENERATOR_PARTS: usize = 4;
/// Hash buckets for the primary-key layouts.
pub const TPCH_HASH_BUCKETS: usize = 2;

/// One fixture statement can scale far beyond the harness's interactive
/// budget: SF10 `lineitem` writes roughly 60 million rows in a single commit.
const FIXTURE_TIMEOUT: Duration = Duration::from_secs(600);

const SCALE_ENV: &str = "LAKESOUL_TPCH_SCALE";
const LAYOUT_ENV: &str = "LAKESOUL_TPCH_LAYOUT";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TpchConfig {
    pub scale: &'static str,
    pub layout: &'static str,
}

impl TpchConfig {
    /// Read the fixture scale and layout, rejecting anything the checked-in
    /// answers and DDL contracts cannot represent.
    pub fn from_env() -> Result<Self> {
        let scale = match env_value(SCALE_ENV)?.as_deref() {
            None | Some("0.1") => "0.1",
            Some("1") => "1",
            Some("10") => "10",
            Some(other) => {
                bail!("{} must be exactly 0.1, 1 or 10; got {other:?}", SCALE_ENV)
            }
        };
        let layout = match env_value(LAYOUT_ENV)?.as_deref() {
            None | Some("pk") => "pk",
            Some("nopk") => "nopk",
            Some("pkmonth") => "pkmonth",
            Some(other) => bail!(
                "{} must be exactly pk, nopk or pkmonth; got {other:?}",
                LAYOUT_ENV
            ),
        };
        Ok(Self { scale, layout })
    }
}

fn env_value(key: &str) -> Result<Option<String>> {
    match std::env::var(key) {
        Ok(value) => Ok(Some(value)),
        Err(VarError::NotPresent) => Ok(None),
        Err(VarError::NotUnicode(_)) => bail!("{key} is not valid UTF-8"),
    }
}

fn scale_literal(scale: &str) -> Result<&'static str> {
    match scale {
        "0.1" => Ok("0.1"),
        "1" => Ok("1.0"),
        "10" => Ok("10.0"),
        other => bail!("TPC-H scale must be 0.1, 1 or 10; got {other:?}"),
    }
}

fn scale_tenths(scale: &str) -> Result<u64> {
    match scale {
        "0.1" => Ok(1),
        "1" => Ok(10),
        "10" => Ok(100),
        other => bail!("TPC-H scale must be 0.1, 1 or 10; got {other:?}"),
    }
}

/// DDL for the fixture tables, copied from `benchmark/datagen/tpch.sh` but
/// without its `DROP`, with the same monetary precision (`DECIMAL(15,2)`) and
/// the four `INT` columns the checked-in answers rely on.
struct TableSpec {
    name: &'static str,
    columns: &'static str,
    primary_key: &'static [&'static str],
    /// Trailing range-partition column and its date source for `pkmonth`.
    month: Option<(&'static str, &'static str)>,
    /// Distinct months the source dates span, used to prove the physical
    /// partition catalog instead of restating the DDL.
    monthly_partitions: u32,
}

