impl StartupState {
    /// Materialize the TPC-H tables in the already-created harness namespace.
    pub(super) async fn create_tpch_fixtures(
        &mut self,
        config: &TpchConfig,
    ) -> Result<()> {
        ensure!(
            matches!(config.scale, "0.1" | "1" | "10"),
            "TPC-H scale must be 0.1, 1 or 10; got {:?}",
            config.scale
        );
        ensure!(
            matches!(config.layout, "pk" | "nopk" | "pkmonth"),
            "TPC-H layout must be pk, nopk or pkmonth; got {:?}",
            config.layout
        );
        // The factory session does not register benchmark table functions;
        // the fixture owns them only for this management session.
        register_tpch_udtfs(&self.management)
            .map_err(|error| anyhow!("register TPC-H UDTFs: {error:?}"))?;
        let scale = scale_literal(config.scale)?;
        let buckets = if config.layout == "nopk" {
            "-".to_owned()
        } else {
            TPCH_HASH_BUCKETS.to_string()
        };
        let mut total_rows = 0_u64;
        let mut total_files = 0_usize;

        for spec in &TABLES {
            let month = if config.layout == "pkmonth" {
                spec.month
            } else {
                None
            };
            let primary_key: &[&str] = if config.layout == "nopk" {
                &[]
            } else {
                spec.primary_key
            };
            let parts = if matches!(spec.name, "nation" | "region") {
                1
            } else {
                TPCH_GENERATOR_PARTS
            };
            let location = format!(
                "{}/{}/{}",
                self.warehouse_url.trim_end_matches('/'),
                self.namespace,
                spec.name
            );

            let mut columns = spec.columns.to_owned();
            if let Some((month_column, _)) = month {
                columns.push_str(&format!(", {month_column} STRING NOT NULL"));
            }
            if !primary_key.is_empty() {
                columns.push_str(&format!(", PRIMARY KEY ({})", primary_key.join(", ")));
            }
            let partitioning = month.map_or_else(String::new, |(column, _)| {
                format!(" PARTITIONED BY ({column})")
            });
            // An unset `file_format` now defaults to Vortex; the fixture
            // contract requires published Parquet files and Parquet types.
            let options = if config.layout == "nopk" {
                " OPTIONS ('file_format' 'parquet')".to_owned()
            } else {
                format!(
                    " OPTIONS ('hashBucketNum' '{}', 'file_format' 'parquet')",
                    TPCH_HASH_BUCKETS
                )
            };
            let create = format!(
                "CREATE EXTERNAL TABLE lakesoul.{}.{} ({columns}) \
                 STORED AS LAKESOUL{partitioning}{options} LOCATION '{location}'",
                self.namespace, spec.name
            );
            fixture_execute(&self.management, &create)
                .await
                .with_context(|| {
                    format!(
                        "create TPC-H table {} (sf={}, layout={})",
                        spec.name, config.scale, config.layout
                    )
                })?;
            // Register immediately: a failure below must still drop this table
            // through the normal teardown.
            self.created_tables.push(spec.name.to_owned());

            let select = month.map_or_else(
                || "*".to_owned(),
                |(column, source)| format!("*, to_char({source}, '%Y-%m') AS {column}"),
            );
            let insert_keyword = if config.layout == "nopk" {
                "INSERT INTO"
            } else {
                "INSERT OR REPLACE INTO"
            };
            let insert = format!(
                "{insert_keyword} lakesoul.{}.{} SELECT {select} FROM tpch_{}({scale}, {parts})",
                self.namespace, spec.name, spec.name
            );
            fixture_execute(&self.management, &insert)
                .await
                .with_context(|| {
                    format!(
                        "populate TPC-H table {} (sf={}, layout={}, parts={parts})",
                        spec.name, config.scale, config.layout
                    )
                })?;

            let proof = self
                .prove_tpch_table(spec, config, month, primary_key)
                .await?;
            eprintln!(
                "tpch fixture proof: sf={} layout={} generator={} parts={parts} \
                 buckets={} table={} pk={} month={} rows={} files={} partitions={}",
                config.scale,
                config.layout,
                TPCH_GENERATOR,
                buckets,
                spec.name,
                if primary_key.is_empty() {
                    "-".to_owned()
                } else {
                    primary_key.join(",")
                },
                month.map_or("-", |(column, _)| column),
                proof.rows,
                proof.files,
                proof.partitions,
            );
            total_rows += proof.rows;
            total_files += proof.files;
        }

        eprintln!(
            "tpch fixtures ready: sf={} layout={} generator={} parts={} \
             buckets={} tables={} rows={total_rows} files={total_files}",
            config.scale,
            config.layout,
            TPCH_GENERATOR,
            TPCH_GENERATOR_PARTS,
            buckets,
            TABLES.len(),
        );
        Ok(())
    }

    /// Prove the committed metadata and published Parquet of one table, never
    /// trusting the SQL statement's success as evidence.
    async fn prove_tpch_table(
        &self,
        spec: &TableSpec,
        config: &TpchConfig,
        month: Option<(&'static str, &'static str)>,
        primary_key: &[&str],
    ) -> Result<TableProof> {
        let table = bounded(FIXTURE_TIMEOUT, "read TPC-H table metadata", async {
            self.meta
                .get_table_info_by_table_name(spec.name, &self.namespace)
                .await
                .map_err(|error| format!("{error:?}"))
        })
        .await?
        .with_context(|| {
            format!(
                "metadata has no TPC-H table {} in namespace {}",
                spec.name, self.namespace
            )
        })?;
        ensure!(
            table.table_namespace == self.namespace,
            "TPC-H table {} belongs to namespace {}, expected {}",
            spec.name,
            table.table_namespace,
            self.namespace
        );
        ensure!(
            table.table_name == spec.name,
            "TPC-H metadata table name is {}, expected {}",
            table.table_name,
            spec.name
        );

        let table_path = local_path(&table.table_path);
        ensure!(
            table_path.is_absolute() && table_path.starts_with(&self.warehouse_dir),
            "TPC-H table {} path is outside the owned warehouse: {}",
            spec.name,
            table.table_path
        );
        ensure!(
            table_path.is_dir(),
            "TPC-H table {} has no physical directory: {}",
            spec.name,
            table.table_path
        );

        let properties: serde_json::Value = serde_json::from_str(&table.properties)
            .with_context(|| {
                format!(
                    "TPC-H table {} properties are not JSON: {}",
                    spec.name, table.properties
                )
            })?;
        ensure!(
            properties
                .get("file_format")
                .and_then(serde_json::Value::as_str)
                == Some("parquet"),
            "TPC-H table {} is not declared as Parquet: {}",
            spec.name,
            table.properties
        );
        let expected_buckets = TPCH_HASH_BUCKETS.to_string();
        match config.layout {
            "nopk" => ensure!(
                properties.get("hashBucketNum").is_none(),
                "nopk TPC-H table {} unexpectedly declares hash buckets: {}",
                spec.name,
                table.properties
            ),
            _ => ensure!(
                properties
                    .get("hashBucketNum")
                    .and_then(serde_json::Value::as_str)
                    == Some(expected_buckets.as_str()),
                "TPC-H table {} hashBucketNum is not {expected_buckets}: {}",
                spec.name,
                table.properties
            ),
        }

        let range_key = month.map_or("", |(column, _)| column);
        let hash_keys = primary_key.join(",");
        let declared = format!("{range_key};{hash_keys}");
        ensure!(
            table.partitions == declared,
            "TPC-H table {} metadata partitions are {:?}, expected {declared:?}",
            spec.name,
            table.partitions
        );

        let partitions = bounded(FIXTURE_TIMEOUT, "read TPC-H partitions", async {
            self.meta
                .get_all_partition_info(&table.table_id)
                .await
                .map_err(|error| format!("{error:?}"))
        })
        .await?;
        let expected_month_values =
            month.map(|_| expected_months(spec.monthly_partitions));
        match (month, expected_month_values.as_ref()) {
            (Some((month_column, _)), Some(expected_months)) => {
                ensure!(
                    partitions.len() == spec.monthly_partitions as usize,
                    "TPC-H table {} has {} month partition(s), expected {}",
                    spec.name,
                    partitions.len(),
                    spec.monthly_partitions
                );
                let mut actual_months = BTreeSet::new();
                for partition in &partitions {
                    ensure!(
                        !partition.snapshot.is_empty(),
                        "TPC-H table {} partition {} has no committed snapshot",
                        spec.name,
                        partition.partition_desc
                    );
                    let prefix = format!("{month_column}=");
                    let value = partition
                        .partition_desc
                        .strip_prefix(prefix.as_str())
                        .with_context(|| {
                            format!(
                                "TPC-H table {} partition desc {:?} lacks {month_column}=",
                                spec.name, partition.partition_desc
                            )
                        })?;
                    ensure!(
                        is_year_month(value),
                        "TPC-H table {} partition value {value:?} is not YYYY-MM",
                        spec.name
                    );
                    ensure!(
                        actual_months.insert(value.to_owned()),
                        "TPC-H table {} repeats partition {value}",
                        spec.name
                    );
                }
                ensure!(
                    &actual_months == expected_months,
                    "TPC-H table {} month partitions are {:?}, expected 1992-01 through \
                     the source date range",
                    spec.name,
                    actual_months
                );
            }
            _ => {
                ensure!(
                    partitions.len() == 1,
                    "unpartitioned TPC-H table {} has {} metadata partitions",
                    spec.name,
                    partitions.len()
                );
                ensure!(
                    partitions[0].partition_desc == "-5",
                    "unpartitioned TPC-H table {} partition desc is {:?}, expected -5",
                    spec.name,
                    partitions[0].partition_desc
                );
                ensure!(
                    !partitions[0].snapshot.is_empty(),
                    "TPC-H table {} has no committed snapshot",
                    spec.name
                );
            }
        }

        let files = bounded(FIXTURE_TIMEOUT, "read TPC-H data files", async {
            self.meta
                .get_data_files_by_table_name(spec.name, &self.namespace)
                .await
                .map_err(|error| format!("{error:?}"))
        })
        .await?;
        ensure!(
            !files.is_empty(),
            "TPC-H table {} published no active files",
            spec.name
        );

        let mut unique = BTreeSet::new();
        let mut total_rows = 0_u64;
        let mut file_months = BTreeSet::new();
        for file in &files {
            ensure!(
                unique.insert(file.as_str()),
                "TPC-H table {} lists duplicate active file {file}",
                spec.name
            );
            let path = local_path(file);
            ensure!(
                path.is_absolute() && path.starts_with(&self.warehouse_dir),
                "TPC-H table {} file is outside the owned warehouse: {file}",
                spec.name
            );
            ensure!(
                path.is_file(),
                "TPC-H table {} file is missing: {file}",
                spec.name
            );
            let handle = File::open(path)
                .with_context(|| format!("open TPC-H Parquet file {file}"))?;
            let builder = ParquetRecordBatchReaderBuilder::try_new(handle)
                .with_context(|| format!("read Parquet footer of TPC-H file {file}"))?;
            let rows = builder.metadata().file_metadata().num_rows();
            ensure!(
                rows > 0,
                "TPC-H table {} file contains no rows: {file}",
                spec.name
            );
            let rows = u64::try_from(rows).map_err(|error| {
                anyhow!("negative Parquet row count in {file}: {error}")
            })?;
            total_rows = total_rows
                .checked_add(rows)
                .context("TPC-H row count overflow")?;
            check_physical_schema(spec, config.layout, month, file, builder.schema())?;
            if let Some((month_column, _)) = month {
                let marker = format!("/{month_column}=");
                let (_, remainder) = file.split_once(marker.as_str()).with_context(|| {
                    format!(
                        "TPC-H table {} file is not under a {month_column}= partition: {file}",
                        spec.name
                    )
                })?;
                let value = remainder.split('/').next().unwrap_or_default();
                ensure!(
                    is_year_month(value),
                    "TPC-H table {} file has invalid month directory {value:?}: {file}",
                    spec.name
                );
                file_months.insert(value.to_owned());
            }
        }
        if let Some(expected_months) = expected_month_values.as_ref() {
            ensure!(
                &file_months == expected_months,
                "TPC-H table {} physical files cover months {:?}, expected {:?}",
                spec.name,
                file_months,
                expected_months
            );
        }

        let expected = expected_rows(spec.name, config.scale)?;
        ensure!(
            total_rows == expected,
            "TPC-H table {} committed rows: {total_rows}, expected {expected} at sf={}",
            spec.name,
            config.scale
        );
        Ok(TableProof {
            rows: total_rows,
            files: unique.len(),
            partitions: partitions.len(),
        })
    }
}

struct TableProof {
    rows: u64,
    files: usize,
    partitions: usize,
}

fn local_path(url: &str) -> &Path {
    Path::new(url.strip_prefix("file://").unwrap_or(url))
}

fn expected_months(count: u32) -> BTreeSet<String> {
    let mut months = BTreeSet::new();
    let (mut year, mut month) = (1992_u32, 1_u32);
    for _ in 0..count {
        months.insert(format!("{year:04}-{month:02}"));
        month += 1;
        if month > 12 {
            month = 1;
            year += 1;
        }
    }
    months
}

fn is_year_month(value: &str) -> bool {
    let bytes = value.as_bytes();
    if value.len() != 7 || !value.is_ascii() || bytes[4] != b'-' {
        return false;
    }
    if !bytes[..4].iter().all(|byte| byte.is_ascii_digit())
        || !bytes[5..].iter().all(|byte| byte.is_ascii_digit())
    {
        return false;
    }
    let month = u32::from(bytes[5] - b'0') * 10 + u32::from(bytes[6] - b'0');
    (1..=12).contains(&month)
}

enum ColumnKind {
    Money,
    Int32,
    Int64,
    Date,
    Text,
}

/// The checked-in answers rely on 15-digit money with two decimals, `INT` in
/// the four TPC-H integer columns, 64-bit keys and dates.
fn column_kind(name: &str) -> Option<ColumnKind> {
    match name {
        "l_quantity" | "l_extendedprice" | "l_discount" | "l_tax" | "o_totalprice"
        | "p_retailprice" | "ps_supplycost" | "s_acctbal" | "c_acctbal" => {
            Some(ColumnKind::Money)
        }
        "p_size" | "ps_availqty" | "o_shippriority" | "l_linenumber" => {
            Some(ColumnKind::Int32)
        }
        "l_shipdate" | "l_commitdate" | "l_receiptdate" | "o_orderdate" => {
            Some(ColumnKind::Date)
        }
        "o_ordermonth" | "l_shipmonth" => Some(ColumnKind::Text),
        _ if name.ends_with("key") => Some(ColumnKind::Int64),
        _ => None,
    }
}

fn check_physical_schema(
    spec: &TableSpec,
    layout: &str,
    month: Option<(&'static str, &'static str)>,
    file: &str,
    schema: &Schema,
) -> Result<()> {
    for field in schema.fields() {
        let Some(kind) = column_kind(field.name()) else {
            continue;
        };
        let data_type = field.data_type();
        let valid = match kind {
            ColumnKind::Money => matches!(data_type, DataType::Decimal128(15, 2)),
            ColumnKind::Int32 => matches!(data_type, DataType::Int32),
            ColumnKind::Int64 => matches!(data_type, DataType::Int64),
            ColumnKind::Date => matches!(data_type, DataType::Date32),
            ColumnKind::Text => matches!(
                data_type,
                DataType::Utf8 | DataType::LargeUtf8 | DataType::Utf8View
            ),
        };
        ensure!(
            valid,
            "TPC-H table {} file {file} column {} has physical type {data_type:?}",
            spec.name,
            field.name()
        );
    }
    if let Some((month_column, _)) = month {
        ensure!(
            layout != "pkmonth"
                || !schema
                    .fields()
                    .iter()
                    .any(|field| field.name().as_str() == month_column),
            "TPC-H table {} stores range-partition column {month_column} in file {file}",
            spec.name
        );
    }
    Ok(())
}

/// Known TPC-H dbgen cardinalities; `lineitem` is not a simple multiple of the
/// scale factor, so its three checked-in scales are listed explicitly. The
/// values follow tpchgen-rs's `RandomBoundedInt` line-count stream, which
/// reproduces the reference `sf-0.001`/`sf-0.01` files exactly.
fn expected_rows(table: &str, scale: &str) -> Result<u64> {
    let tenths = scale_tenths(scale)?;
    let scaled = |base: u64| base * tenths / 10;
    let rows = match table {
        "nation" => 25,
        "region" => 5,
        "supplier" => scaled(10_000),
        "customer" => scaled(150_000),
        "part" => scaled(200_000),
        "partsupp" => scaled(800_000),
        "orders" => scaled(1_500_000),
        "lineitem" => match scale {
            "0.1" => 600_572,
            "1" => 6_001_215,
            "10" => 59_986_052,
            other => bail!("TPC-H lineitem cardinality for unsupported scale {other:?}"),
        },
        other => bail!("unknown TPC-H table {other}"),
    };
    Ok(rows)
}

/// Run one fixture statement to completion. `collect` drains the write plan,
/// so success means the commit and its metadata publication have finished.
async fn fixture_execute(context: &SessionContext, sql: &str) -> Result<()> {
    match tokio::time::timeout(FIXTURE_TIMEOUT, async {
        let frame = context.sql(sql).await.map_err(|error| error.to_string())?;
        frame
            .collect()
            .await
            .map(|_| ())
            .map_err(|error| error.to_string())
    })
    .await
    {
        Err(_) => bail!(
            "fixture statement timed out after {:?}: {sql}",
            FIXTURE_TIMEOUT
        ),
        Ok(Err(error)) => Err(anyhow!("fixture statement failed: {sql}: {error}")),
        Ok(Ok(())) => Ok(()),
    }
}
